/**
 * PreviewAnswerControl — dispatches one question to its respondent-side
 * control (story #1284), covering the proto's canonical 10 `QuestionType`s.
 *
 * These are GENUINELY INTERACTIVE, unlike `editor/QuestionAnswerPreview.tsx`,
 * which is deliberately non-interactive plain markup for the author's card. Both
 * exist on purpose: the editor preview answers "what shape will respondents
 * see," and never wants a focusable control inside an authoring card; this
 * answers "what will respondents actually do," and Submit validates what they
 * did. Neither can be expressed as the other with a flag without making one of
 * them worse.
 *
 * Nothing here persists anything — see `lib/previewAnswers.ts` for why a
 * preview must not write a response row.
 *
 * The three multi-line/complex shapes live in their own files
 * (`PreviewRankList`, `PreviewMatrixGrid`); the seven single-control shapes are
 * inline below, since each is a handful of lines and splitting them further
 * would spread one decision (how a choice group looks) across seven files.
 */

import { type ReactElement } from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { QUESTION_CONFIG_KEYS, readString } from "../../api/questionConfig";
import { CHOICE_GROUP_ATTR, handleChoiceKeyDown } from "../../lib/choiceKeyboard";
import {
  matrixAllowsMultiple,
  matrixColumnsFor,
  matrixRowsFor,
  optionsFor,
  scaleLabelsFor,
  scaleStopsFor,
  setMatrixCell,
  toggleChoice,
  type PreviewAnswer,
} from "../../lib/previewAnswers";
import { BASE_TEXTAREA_CLASSNAME } from "../../lib/textareaClassName";
import { PreviewMatrixGrid } from "./PreviewMatrixGrid";
import { PreviewRankList } from "./PreviewRankList";
import type { QuestionDTO } from "../../api/questions";

export interface PreviewAnswerControlProps {
  readonly question: QuestionDTO;
  readonly answer: PreviewAnswer;
  readonly onChange: (next: PreviewAnswer) => void;
  /** Id of the element naming this question, for grouping controls. */
  readonly labelledBy: string;
  /** Id of the inline error, when this question has one. */
  readonly errorId?: string;
  readonly invalid: boolean;
}

const OPTION_ROW_CLASSNAME =
  "flex items-center gap-cog-3 rounded-md border border-cog-border bg-cog-surface px-cog-3 py-cog-2 text-body-md text-cog-text-primary transition-colors duration-standard hover:bg-cog-surface-subtle";

const FIELD_INVALID_CLASSNAME =
  "border-cog-danger-500 dark:border-cog-danger-dark";

/** Radio group — `single_select`, `yes_no`, `true_false`. */
function ChoiceGroup({
  question,
  answer,
  onChange,
  labelledBy,
  errorId,
}: PreviewAnswerControlProps): ReactElement {
  const options = optionsFor(question);
  const current = answer.kind === "choice" ? answer.choice : "";
  return (
    <div
      role="radiogroup"
      aria-labelledby={labelledBy}
      aria-describedby={errorId}
      className="flex flex-col gap-cog-2"
    >
      <p className="text-caption text-cog-text-tertiary">
        {m.ask_survey_preview_select_one_hint()}
      </p>
      {options.map((option) => (
        <label key={option} className={OPTION_ROW_CLASSNAME}>
          <input
            type="radio"
            name={question.id}
            value={option}
            checked={current === option}
            onChange={() => onChange({ kind: "choice", choice: option })}
            // Enter only. Arrow keys already move AND select across a native
            // radio `name` group, so `roving` stays off here.
            onKeyDown={(event) =>
              handleChoiceKeyDown(event, {
                onActivate: () => onChange({ kind: "choice", choice: option }),
              })
            }
            className="h-cog-4-5 w-cog-4-5 rounded-pill accent-cog-blue-600 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus"
          />
          <span data-i18n-allow="data">{option}</span>
        </label>
      ))}
    </div>
  );
}

/** Checkbox group — `multiple_select`. */
function ChoicesGroup({
  question,
  answer,
  onChange,
  labelledBy,
  errorId,
}: PreviewAnswerControlProps): ReactElement {
  const options = optionsFor(question);
  const current = answer.kind === "choices" ? answer.choices : [];
  return (
    <div
      role="group"
      aria-labelledby={labelledBy}
      aria-describedby={errorId}
      // Scopes arrow-key focus movement to this question's checkboxes.
      {...{ [CHOICE_GROUP_ATTR]: "" }}
      className="flex flex-col gap-cog-2"
    >
      <p className="text-caption text-cog-text-tertiary">
        {m.ask_survey_preview_select_many_hint()}
      </p>
      {options.map((option) => (
        <label key={option} className={OPTION_ROW_CLASSNAME}>
          <input
            type="checkbox"
            checked={current.includes(option)}
            onChange={() =>
              onChange({
                kind: "choices",
                choices: toggleChoice(current, option, options),
              })
            }
            // Enter toggles, and arrows move focus across the group — a
            // checkbox has neither natively. Arrows deliberately do NOT toggle;
            // see choiceKeyboard.ts.
            onKeyDown={(event) =>
              handleChoiceKeyDown(event, {
                roving: true,
                onActivate: () =>
                  onChange({
                    kind: "choices",
                    choices: toggleChoice(current, option, options),
                  }),
              })
            }
            className="h-cog-4-5 w-cog-4-5 rounded-md accent-cog-blue-600 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus"
          />
          <span data-i18n-allow="data">{option}</span>
        </label>
      ))}
    </div>
  );
}

/** Radio row with end labels — `scale`. */
function ScaleRow({
  question,
  answer,
  onChange,
  labelledBy,
  errorId,
}: PreviewAnswerControlProps): ReactElement {
  const stops = scaleStopsFor(question);
  const { low, high } = scaleLabelsFor(question);
  const current = answer.kind === "scale" ? answer.scale : null;
  const first = stops[0];
  const last = stops[stops.length - 1];

  const rangeId = `${question.id}-scale-range`;
  return (
    <div
      role="radiogroup"
      // Both the prompt AND the range, via aria-labelledby. An `aria-label`
      // alongside `aria-labelledby` is dead weight — labelledby wins, so the
      // range string (and its 11 translations) would never be announced.
      aria-labelledby={`${labelledBy} ${rangeId}`}
      aria-describedby={errorId}
      className="flex flex-col gap-cog-2"
    >
      <span id={rangeId} className="sr-only">
        {m.ask_survey_preview_scale_group_label({ min: first, max: last })}
      </span>
      <div className="flex flex-wrap items-center gap-cog-2">
        {stops.map((stop) => {
          const checked = current === stop;
          return (
            <label
              key={stop}
              className={[
                // `relative` is LOAD-BEARING — see the input's comment below.
                "relative inline-flex min-h-tap min-w-tap cursor-pointer items-center justify-center rounded-md border px-cog-3 text-body-md tabular-nums transition-colors duration-standard",
                // The focus ring rides the LABEL — the input is transparent, so
                // its own ring would be invisible. `has-[:focus-visible]`, not
                // `peer-focus-visible`: `peer-*` styles a SIBLING of the peer,
                // and this label is the input's PARENT, so the peer variants
                // would have compiled to selectors that never match.
                "has-[:focus-visible]:outline has-[:focus-visible]:outline-2 has-[:focus-visible]:outline-offset-2 has-[:focus-visible]:outline-cog-focus",
                checked
                  ? "border-cog-blue-600 bg-cog-blue-50 font-semibold text-cog-blue-700 dark:bg-cog-blue-950 dark:text-cog-blue-300"
                  : "border-cog-border bg-cog-surface text-cog-text-primary hover:bg-cog-surface-subtle",
              ].join(" ")}
            >
              <input
                type="radio"
                name={question.id}
                value={stop}
                checked={checked}
                onChange={() => onChange({ kind: "scale", scale: stop })}
                // Enter only — native arrows already traverse the scale.
                onKeyDown={(event) =>
                  handleChoiceKeyDown(event, {
                    onActivate: () => onChange({ kind: "scale", scale: stop }),
                  })
                }
                // NOT `sr-only`. That utility is `position: absolute` with a
                // -1px margin and a 1px clip, and this label was not a
                // positioned ancestor — so the input resolved against whatever
                // WAS, landing far from its tile. Clicking the tile focuses the
                // input, the browser scrolls the focused element into view, and
                // the preview's `overflow-y-auto` container jumped to that
                // stray coordinate: the page appeared to go blank. It reproduced
                // only in a real browser, because jsdom has no layout engine and
                // never scrolls.
                //
                // Instead the input FILLS its own tile (`inset-cog-0` against the
                // now-`relative` label) and is merely transparent. It stays a
                // real focusable radio — so arrow-key navigation across the
                // group is unchanged — but "scroll the focused element into
                // view" now means "scroll to this tile", which is correct. It
                // also makes the whole tile a hit target rather than 1px of it.
                className="absolute inset-cog-0 m-cog-0 h-full w-full cursor-pointer appearance-none opacity-0"
              />
              {stop}
            </label>
          );
        })}
      </div>
      {(low !== undefined || high !== undefined) && (
        <div className="flex justify-between text-caption text-cog-text-tertiary">
          <span data-i18n-allow="data">{low ?? ""}</span>
          <span data-i18n-allow="data">{high ?? ""}</span>
        </div>
      )}
    </div>
  );
}

/** Textarea — `free_text`. */
function TextField({
  question,
  answer,
  onChange,
  labelledBy,
  errorId,
  invalid,
}: PreviewAnswerControlProps): ReactElement {
  const configured = readString(question.config, QUESTION_CONFIG_KEYS.placeholder);
  const value = answer.kind === "text" ? answer.text : "";
  return (
    <textarea
      aria-labelledby={labelledBy}
      aria-describedby={errorId}
      aria-invalid={invalid}
      value={value}
      onChange={(event) => onChange({ kind: "text", text: event.target.value })}
      rows={3}
      // An author-configured placeholder wins; otherwise the respondent-facing
      // default ("Type your answer…") rather than the editor's third-person
      // "Respondent types their answer…", which would read oddly TO the
      // respondent.
      placeholder={
        configured !== undefined && configured !== ""
          ? configured
          : m.ask_survey_preview_text_placeholder()
      }
      className={[BASE_TEXTAREA_CLASSNAME, invalid ? FIELD_INVALID_CLASSNAME : ""]
        .join(" ")
        .trim()}
    />
  );
}

/** Native date input — `date`. */
function DateField({
  question,
  answer,
  onChange,
  labelledBy,
  errorId,
  invalid,
}: PreviewAnswerControlProps): ReactElement {
  const min = readString(question.config, QUESTION_CONFIG_KEYS.dateMin);
  const max = readString(question.config, QUESTION_CONFIG_KEYS.dateMax);
  const value = answer.kind === "text" ? answer.text : "";
  return (
    <input
      type="date"
      aria-labelledby={labelledBy}
      aria-describedby={errorId}
      aria-invalid={invalid}
      value={value}
      min={min !== "" ? min : undefined}
      max={max !== "" ? max : undefined}
      onChange={(event) => onChange({ kind: "text", text: event.target.value })}
      className={[
        "min-h-input w-full max-w-xs rounded-md border bg-cog-surface px-cog-3 text-body-md text-cog-text-primary",
        "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus",
        invalid ? FIELD_INVALID_CLASSNAME : "border-cog-border",
      ].join(" ")}
    />
  );
}

/** Numeric text input — `number`. */
function NumberField({
  answer,
  onChange,
  labelledBy,
  errorId,
  invalid,
}: PreviewAnswerControlProps): ReactElement {
  const value = answer.kind === "text" ? answer.text : "";
  return (
    <input
      // `type="text"` + `inputMode="numeric"`, matching the editor's own
      // divergence 8 (§11.1): a native number input's spinner and its silent
      // value-clearing on an intermediate state ("-", "1.") lose the
      // respondent's in-progress entry.
      type="text"
      aria-labelledby={labelledBy}
      aria-describedby={errorId}
      aria-invalid={invalid}
      value={value}
      onChange={(event) => onChange({ kind: "text", text: event.target.value })}
      placeholder={m.ask_survey_preview_number_placeholder()}
      // NO aria-valuemin/aria-valuemax here. Those are range-family attributes
      // (spinbutton/slider); on this control's implicit `textbox` role assistive
      // tech drops them and axe flags them, so they described an effect that
      // never happened. The bounds reach the respondent through the question's
      // own help text and through validateAnswer's message on submit.
      inputMode="numeric"
      className={[
        "min-h-input w-full max-w-xs rounded-md border bg-cog-surface px-cog-3 text-body-md tabular-nums text-cog-text-primary",
        "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus",
        invalid ? FIELD_INVALID_CLASSNAME : "border-cog-border",
      ].join(" ")}
    />
  );
}

export function PreviewAnswerControl(props: PreviewAnswerControlProps): ReactElement {
  const { question, answer, onChange, labelledBy } = props;

  switch (question.questionType) {
    case "single_select":
    case "yes_no":
    case "true_false":
      return <ChoiceGroup {...props} />;
    case "multiple_select":
      return <ChoicesGroup {...props} />;
    case "scale":
      return <ScaleRow {...props} />;
    case "rank_order":
      return (
        <PreviewRankList
          ranking={answer.kind === "ranking" ? answer.ranking : []}
          labelledBy={labelledBy}
          onChange={(ranking) => onChange({ kind: "ranking", ranking })}
        />
      );
    case "matrix": {
      const columns = matrixColumnsFor(question);
      const allowMultiple = matrixAllowsMultiple(question);
      return (
        <PreviewMatrixGrid
          questionId={question.id}
          rows={matrixRowsFor(question)}
          columns={columns}
          allowMultiple={allowMultiple}
          selected={answer.kind === "matrix" ? answer.matrix : {}}
          onToggle={(row, column) =>
            onChange({
              kind: "matrix",
              matrix: setMatrixCell(
                answer.kind === "matrix" ? answer.matrix : {},
                row,
                column,
                allowMultiple,
                columns,
              ),
            })
          }
        />
      );
    }
    case "date":
      return <DateField {...props} />;
    case "number":
      return <NumberField {...props} />;
    // free_text, plus "unspecified" — normalizeQuestion's defensive fallback
    // for an unrecognized wire value. A textarea collects something rather
    // than rendering an unanswerable blank.
    default:
      return <TextField {...props} />;
  }
}


