/**
 * PreviewMatrixGrid — the respondent-side `matrix` control (story #1284).
 *
 * A real `<table>` with `<th scope="col">` / `<th scope="row">`, matching the
 * semantics `QuestionAnswerPreview`'s read-only matrix already uses: a data
 * grid genuinely benefits from table semantics, and a screen reader announces
 * each cell's row and column headers automatically, which is the only way a
 * respondent can tell what an unlabelled radio in the middle of a grid means.
 *
 * Cell shape follows the editor's own rule (docs/design/ask-survey-editor.md
 * §11.5): a ROUND control when only one column per row may be chosen, a
 * ROUNDED SQUARE when several may. Here they are genuine `<input type="radio">`
 * / `<input type="checkbox">` elements rather than the editor preview's
 * decorative shapes, so native keyboard behaviour (arrow keys within a radio
 * group, space to toggle a checkbox) comes for free.
 *
 * Each row's radios share a `name` scoped to `questionId` + the row label, which
 * is what makes one selection per row mutually exclusive without any JS.
 */

import { type ReactElement } from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { CHOICE_GROUP_ATTR, handleChoiceKeyDown } from "../../lib/choiceKeyboard";

export interface PreviewMatrixGridProps {
  readonly questionId: string;
  readonly rows: readonly string[];
  readonly columns: readonly string[];
  readonly allowMultiple: boolean;
  readonly selected: Readonly<Record<string, readonly string[]>>;
  readonly onToggle: (row: string, column: string) => void;
}

export function PreviewMatrixGrid({
  questionId,
  rows,
  columns,
  allowMultiple,
  selected,
  onToggle,
}: PreviewMatrixGridProps): ReactElement {
  const caption = allowMultiple
    ? m.ask_survey_preview_matrix_caption_multiple()
    : m.ask_survey_preview_matrix_caption_single();

  return (
    // Horizontal overflow is scoped to this wrapper so a wide matrix scrolls
    // itself instead of making the whole preview page scroll sideways.
    <div className="overflow-x-auto">
      <table className="w-full border-collapse text-body-sm">
        <caption className="mb-cog-2 text-start text-body-sm text-cog-text-secondary">
          {caption}
        </caption>
        <thead>
          <tr>
            {/* An empty corner cell — `scope` would be meaningless on it, and a
                visually-hidden label here is read before every row header,
                which is noise rather than help. */}
            <td />
            {columns.map((column) => (
              <th
                key={column}
                scope="col"
                data-i18n-allow="data"
                className="px-cog-2 pb-cog-2 text-center text-caption font-semibold text-cog-text-secondary"
              >
                {column}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => (
            // Arrow-key focus movement is scoped to the row, so a
            // multi-select matrix navigates its own row's columns rather than
            // wrapping into the next row's. Single-select rows share a `name`,
            // so the browser already scopes their native arrow keys the same
            // way — this only matters for the checkbox variant.
            <tr
              key={row}
              {...{ [CHOICE_GROUP_ATTR]: "" }}
              className="border-t border-cog-divider"
            >
              <th
                scope="row"
                data-i18n-allow="data"
                className="py-cog-2 pe-cog-3 text-start text-body-sm font-normal text-cog-text-primary"
              >
                {row}
              </th>
              {columns.map((column) => {
                const checked = (selected[row] ?? []).includes(column);
                return (
                  <td key={column} className="px-cog-2 py-cog-2 text-center">
                    <input
                      type={allowMultiple ? "checkbox" : "radio"}
                      name={`${questionId}:${row}`}
                      checked={checked}
                      onChange={() => onToggle(row, column)}
                      // Enter activates either variant; arrows are added only
                      // for the checkbox one, whose radio counterpart already
                      // has them natively.
                      onKeyDown={(event) =>
                        handleChoiceKeyDown(event, {
                          roving: allowMultiple,
                          onActivate: () => onToggle(row, column),
                        })
                      }
                      // The row/column headers already name this cell for a
                      // screen reader via table semantics, but a standalone
                      // accessible name keeps the control usable in tooling
                      // that flattens the table.
                      aria-label={m.ask_survey_editor_cfg_matrix_cell_aria({
                        row,
                        column,
                      })}
                      className={[
                        "h-cog-4-5 w-cog-4-5 accent-cog-blue-600",
                        "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus",
                        allowMultiple ? "rounded-md" : "rounded-pill",
                      ].join(" ")}
                    />
                  </td>
                );
              })}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}


