/**
 * PreviewFlowRunner — the respondent walk for a BRANCHED survey (story #2302).
 *
 * Story #1284's preview renders every question at once, which is the right
 * shape for a survey that runs straight through and the wrong shape for one
 * that routes: you cannot skip past a question that is already on screen. This
 * component is the paginated alternative — one question at a time, `Next`
 * resolving the route through `lib/surveyTraversal.ts`.
 *
 * IT IS USED ONLY WHEN THE SURVEY ACTUALLY BRANCHES (`hasAnyBranch`). An
 * unbranched survey keeps #1284's single-page scroll untouched, because
 * paginating it would impose a click per question on every author for a feature
 * their survey does not use, and would silently replace a surface that shipped
 * with its own acceptance criteria.
 *
 * **Nothing is persisted**, exactly as in #1284: no `ResponseService.Submit`, no
 * public-route POST, no `ask.responses` row. A preview that recorded a response
 * would inflate `Survey.response_count` and corrupt epic #1291's analytics.
 *
 * THE QUESTION NUMBER IS THE EDITOR'S, NOT THE STEP COUNT. A respondent routed
 * from question 1 to question 4 sees "4." on the next card, not "2.". That is
 * the point: this is a surface for an AUTHOR verifying a route, and the jump in
 * the numbering is the most direct evidence the branch fired. A step counter
 * would hide precisely what the author came here to check. It is also why there
 * is no "question 2 of 7" progress indicator — with branching, the total is not
 * knowable in advance, so any total would be a guess presented as a fact.
 *
 * There is no separate submit step. Reaching the end of the walk IS submitting:
 * when the resolver reports the next step is `end`, the button becomes Submit
 * rather than Next, so a branch straight to the completion screen reads as one.
 */

import {
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactElement,
  type ReactNode,
} from "react";
import { Button } from "@omnicore-platform/ui";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { PreviewQuestionCard } from "./PreviewQuestionCard";
import { buildEditorEntries } from "../../lib/buildEditorEntries";
import { initialAnswer } from "../../lib/previewAnswers";
import {
  buildTraversalMap,
  firstStep,
  resolveNext,
} from "../../lib/surveyTraversal";
import { usePreviewAnswers } from "../../hooks/usePreviewAnswers";
import type { SectionSummary } from "../../api/sections";
import type { QuestionDTO } from "../../api/questions";

/** The section chrome shown above a question that belongs to one. */
interface SectionContext {
  readonly title: string;
  readonly description: string;
  /** True for the section's FIRST member — see the render comment. */
  readonly isFirstMember: boolean;
}

export interface PreviewFlowRunnerProps {
  /**
   * The preview banner and survey header, rendered above the current question.
   *
   * Passed in rather than built here so the branched walk and the single-page
   * scroll cannot present the same survey two different ways, and so the route
   * keeps ownership of what a preview says about itself.
   */
  readonly header: ReactNode;
  /**
   * The survey's live questions. Guaranteed non-empty by the caller's
   * `hasAnyBranch` check — a branch cannot exist without a question to hang
   * off — but the empty case still degrades to the completion screen rather
   * than rendering a card for a question that is not there.
   */
  readonly questions: readonly QuestionDTO[];
  readonly sections: readonly SectionSummary[];
  /** Renders the post-submission screen; owned by the route. */
  readonly renderCompletion: (onRestart: () => void) => ReactElement;
}

export function PreviewFlowRunner({
  header,
  questions,
  sections,
  renderCompletion,
}: PreviewFlowRunnerProps): ReactElement | null {
  const state = usePreviewAnswers(questions);

  // Memoized on the SETTLED inputs, not on `entries`: buildEditorEntries
  // returns a fresh array every call, so keying the memo on its result would
  // rebuild the map on every render and reset nothing but waste work.
  const { map, byId, numberById, sectionById } = useMemo(() => {
    const entries = buildEditorEntries(questions, sections);
    const traversalMap = buildTraversalMap(entries);

    const questionById = new Map<string, QuestionDTO>();
    for (const question of questions) questionById.set(question.id, question);

    // 1-based display number in EDITOR render order — the same number the
    // single-page preview and the editor's own list show for this question.
    const numbers = new Map<string, number>();
    traversalMap.order.forEach((id, index) => numbers.set(id, index + 1));

    const sectionContext = new Map<string, SectionContext>();
    for (const entry of entries) {
      if (entry.kind !== "section") continue;
      entry.questions.forEach((question, index) => {
        sectionContext.set(question.id, {
          title: entry.section.title,
          description: entry.section.description,
          isFirstMember: index === 0,
        });
      });
    }

    return {
      map: traversalMap,
      byId: questionById,
      numberById: numbers,
      sectionById: sectionContext,
    };
  }, [questions, sections]);

  /**
   * The questions visited so far, in order; the last is on screen.
   *
   * A STACK, not an index, because with branching the visited sequence is not
   * derivable from a position — question 4 can follow question 1 — so Previous
   * has to pop what actually happened rather than decrement. Answers for
   * questions popped off and then routed away from are deliberately KEPT in
   * `state.answers`, so a respondent who goes back, changes their mind, and
   * returns down the same route finds their work intact; nothing off the
   * current path is ever validated or shown.
   */
  const [path, setPath] = useState<readonly string[]>(() => {
    const start = firstStep(map);
    return start.kind === "question" ? [start.questionId] : [];
  });

  const currentId = path[path.length - 1];
  const current = currentId === undefined ? undefined : byId.get(currentId);
  // Resolved alongside the question rather than at the point of render, so the
  // "there is a question" and "it has a number" invariants are checked once,
  // together, by the guard below — instead of a `?? 1` fallback at the call
  // site that would quietly mislabel question 4 as "1.".
  const currentNumber = currentId === undefined ? undefined : numberById.get(currentId);

  const cardRef = useRef<HTMLOListElement>(null);
  const hasRenderedRef = useRef(false);
  // Move focus to the new step's container on every advance and every step
  // back. Without it a keyboard or screen-reader user presses Next and focus
  // stays on a button whose label may not even have changed, with no signal
  // that the question behind it did. The container (not the control) is the
  // target so the prompt is announced before the input it labels.
  useEffect(() => {
    if (state.submitted) return;
    // NOT on the first render. Arriving at the preview should leave focus at
    // the top of the document, where the "nothing is saved" notice and the
    // survey title are; jumping straight into the form would skip past both
    // and is the one focus move the respondent did not ask for.
    if (!hasRenderedRef.current) {
      hasRenderedRef.current = true;
      return;
    }
    cardRef.current?.focus();
  }, [currentId, state.submitted]);

  if (state.submitted) {
    return renderCompletion(() => {
      const start = firstStep(map);
      setPath(start.kind === "question" ? [start.questionId] : []);
      state.restart();
    });
  }

  // No question to show. Deliberately NOT the completion screen, which would
  // tell a respondent their response was received when they submitted nothing.
  // The route renders the empty state above the mode fork and `hasAnyBranch`
  // guarantees at least one question, so this is unreachable twice over —
  // which is exactly why it must not say something confidently wrong.
  //
  // `currentNumber` rides along in the same guard: both maps are built from the
  // one `map.order` that produced `currentId`, so either both resolve or the
  // question is not in the survey. Pairing them keeps the number honest without
  // a non-null assertion.
  if (current === undefined || currentNumber === undefined) return null;

  const answer = state.answers[current.id] ?? initialAnswer(current);
  // Resolved from the answer as it stands RIGHT NOW, which is what makes the
  // button label honest: picking the option that routes to the completion
  // screen turns Next into Submit before the respondent commits to it.
  const nextStep = resolveNext(map, current.id, answer);
  const isFinalStep = nextStep.kind === "end";
  const sectionContext = sectionById.get(current.id);

  function handleNext(): void {
    // Only the question on screen is validated. A branched survey never shows
    // every question, so enforcing the whole list would block Submit on a
    // required question the respondent's route legitimately skipped.
    if (current === undefined || !state.validateOne(current.id)) return;
    if (nextStep.kind === "end") {
      state.markSubmitted();
      return;
    }
    setPath((current_) => [...current_, nextStep.questionId]);
  }

  function handlePrevious(): void {
    setPath((current_) => (current_.length > 1 ? current_.slice(0, -1) : current_));
  }

  return (
    <div>
      {header}

      {sectionContext !== undefined && (
        <div className="mb-cog-3">
          {/* The section TITLE rides along on every one of its questions: with
              one question on screen at a time, it is the only thing telling the
              respondent which part of the survey they are in. The DESCRIPTION
              appears on the first member only — it is introductory copy, and
              repeating it above every question would bury the question. */}
          <h2
            data-i18n-allow="data"
            className="text-heading-lg font-semibold text-cog-text-primary"
          >
            {sectionContext.title}
          </h2>
          {sectionContext.isFirstMember && sectionContext.description !== "" && (
            <p
              data-i18n-allow="data"
              className="mt-cog-1 text-body-md text-cog-text-secondary"
            >
              {sectionContext.description}
            </p>
          )}
        </div>
      )}

      {/* PreviewQuestionCard renders an <li>, so it needs a list parent to be
          valid — and it is reused rather than reshaped precisely so a branched
          walk and the single-page scroll cannot drift apart in how a question
          looks, numbers itself, or reports a validation error. tabIndex -1
          makes this the focus target on each step without adding a tab stop. */}
      <ol
        ref={cardRef}
        tabIndex={-1}
        aria-label={m.ask_survey_preview_current_question_label()}
        className="flex list-none flex-col p-cog-0 focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-cog-focus"
      >
        <PreviewQuestionCard
          key={current.id}
          question={current}
          number={currentNumber}
          answer={answer}
          onChange={(next) => state.setAnswer(current.id, next)}
          error={state.errors[current.id]}
        />
      </ol>

      <div className="mt-cog-5 flex items-center justify-between gap-cog-3">
        <Button
          type="button"
          variant="secondary"
          onClick={handlePrevious}
          disabled={path.length <= 1}
        >
          {m.ask_survey_preview_previous_cta()}
        </Button>
        <Button type="button" onClick={handleNext}>
          {isFinalStep
            ? m.ask_survey_preview_submit_cta()
            : m.ask_survey_preview_next_cta()}
        </Button>
      </div>
    </div>
  );
}


