/**
 * PreviewQuestionCard — one question as a respondent sees it (story #1284):
 * number, prompt, Required marker, author help text, the interactive control,
 * and the inline validation error.
 *
 * The Required marker is TEXT, never a bare asterisk or a colour: design.md §0
 * ("never colour alone") applies just as much to a respondent surface, and an
 * unexplained `*` is exactly the pattern that makes required fields ambiguous.
 * It reuses `ask_survey_detail_question_required_label`, already translated in
 * all 11 locales, rather than adding a parallel key that could drift from it.
 *
 * `data-question-id` is what lets the route focus the first invalid question on
 * a failed submit without threading refs through every control variant.
 */

import { type ReactElement } from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { QUESTION_CONFIG_KEYS, readString } from "../../api/questionConfig";
import { PreviewAnswerControl } from "./PreviewAnswerControl";
import type { PreviewAnswer, PreviewValidationError } from "../../lib/previewAnswers";
import type { QuestionDTO } from "../../api/questions";

export interface PreviewQuestionCardProps {
  readonly question: QuestionDTO;
  /** 1-based display number, derived from render order (never stored). */
  readonly number: number;
  readonly answer: PreviewAnswer;
  readonly onChange: (next: PreviewAnswer) => void;
  readonly error?: PreviewValidationError;
}

/**
 * Maps a validation code to its localized message. Kept here rather than in
 * `lib/previewAnswers.ts` so that module stays i18n-free and unit-testable
 * without the paraglide runtime — the same split `questionConfigRules.ts` uses.
 * A new code added there without a branch here would be a type error.
 */
export function validationMessage(error: PreviewValidationError): string {
  switch (error.code) {
    case "required":
      return m.ask_survey_preview_required_error();
    case "text_too_short":
      return m.ask_survey_preview_text_too_short({ min: error.min });
    case "text_too_long":
      return m.ask_survey_preview_text_too_long({ max: error.max });
    case "number_invalid":
      return m.ask_survey_preview_number_invalid();
    case "number_out_of_range":
      return m.ask_survey_preview_number_out_of_range({
        min: error.min,
        max: error.max,
      });
    case "date_out_of_range":
      return m.ask_survey_preview_date_out_of_range({
        min: error.min,
        max: error.max,
      });
    case "number_too_small":
      return m.ask_survey_preview_number_too_small({ min: error.min });
    case "number_too_large":
      return m.ask_survey_preview_number_too_large({ max: error.max });
    case "date_too_early":
      return m.ask_survey_preview_date_too_early({ min: error.min });
    case "date_too_late":
      return m.ask_survey_preview_date_too_late({ max: error.max });
  }
}

export function PreviewQuestionCard({
  question,
  number,
  answer,
  onChange,
  error,
}: PreviewQuestionCardProps): ReactElement {
  const promptId = `preview-q-${question.id}-prompt`;
  const errorId = `preview-q-${question.id}-error`;
  const helpText = readString(question.config, QUESTION_CONFIG_KEYS.helpText);
  const hasHelp = helpText !== undefined && helpText !== "";

  return (
    <li
      data-question-id={question.id}
      className="rounded-xl border border-cog-border bg-cog-surface p-cog-5 shadow-cog-e1"
    >
      <div className="mb-cog-3">
        <p id={promptId} className="text-body-md font-semibold text-cog-text-primary">
          <span className="me-cog-2 tabular-nums text-cog-text-tertiary">{number}.</span>
          <span data-i18n-allow="data">{question.prompt}</span>
          {question.required && (
            <span className="ms-cog-2 text-body-sm font-normal text-cog-danger-700 dark:text-cog-danger-dark">
              {m.ask_survey_detail_question_required_label()}
            </span>
          )}
        </p>
        {hasHelp && (
          <p
            data-i18n-allow="data"
            className="mt-cog-1 text-body-sm text-cog-text-secondary"
          >
            {helpText}
          </p>
        )}
      </div>

      <PreviewAnswerControl
        question={question}
        answer={answer}
        onChange={onChange}
        labelledBy={promptId}
        errorId={error !== undefined ? errorId : undefined}
        invalid={error !== undefined}
      />

      {error !== undefined && (
        <p
          id={errorId}
          role="alert"
          className="mt-cog-2 text-body-sm text-cog-danger-700 dark:text-cog-danger-dark"
        >
          {validationMessage(error)}
        </p>
      )}
    </li>
  );
}


