/**
 * PreviewRankList — the respondent-side `rank_order` control (story #1284).
 *
 * **Reordering is by explicit Up/Down buttons, not drag-and-drop.** The editor
 * side of ranking (`OptionListEditor`, `SurveyQuestionsDndList`) uses dnd-kit
 * because an AUTHOR arranging a list benefits from direct manipulation. This is
 * a different job: the control must be operable by keyboard as a first-class
 * path, not as a dnd-kit `KeyboardSensor` afterthought — that sensor builds its
 * own candidate list and ignores the `collisionDetection` a pointer drag uses,
 * so the two input methods have to be verified separately and can silently
 * disagree. A pair of buttons is the same capability with one code path, an
 * unambiguous accessible name per action, and a live announcement of the
 * resulting position.
 *
 * Both buttons stay rendered at every position and are natively `disabled` at
 * the ends. That is the correct use of `disabled` here — unlike the editor's
 * `aria-disabled` affordances for "unavailable feature," an end-of-list arrow
 * is a momentary, self-evident state, and keeping it focusable would offer a
 * respondent a control that can never do anything.
 */

import { type ReactElement, useLayoutEffect, useRef } from "react";
import { ArrowDown, ArrowUp } from "@omnicore-platform/ui/icons";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { moveRankItem } from "../../lib/previewAnswers";

export interface PreviewRankListProps {
  readonly ranking: readonly string[];
  readonly onChange: (next: readonly string[]) => void;
  /** Ties the list to its question's prompt for assistive tech. */
  readonly labelledBy: string;
}

export function PreviewRankList({
  ranking,
  onChange,
  labelledBy,
}: PreviewRankListProps): ReactElement {
  // Button handles keyed by POSITION, not by item label. Labels are not unique:
  // nothing dedupes options, so an author (or a CSV import) can ship a
  // `rank_order` question with two identical labels. Keyed by label, both rows
  // would share one entry, the second row's ref callback would overwrite the
  // first, and focus restore could land on the other row's button. A position is
  // unique by construction.
  const buttonsRef = useRef(
    new Map<number, { up: HTMLButtonElement | null; down: HTMLButtonElement | null }>(),
  );
  /** Where the moved item LANDED, and which direction took it there. */
  const pendingFocusRef = useRef<{ index: number; delta: number } | null>(null);

  function handles(index: number) {
    const existing = buttonsRef.current.get(index);
    if (existing !== undefined) return existing;
    const created = { up: null as HTMLButtonElement | null, down: null as HTMLButtonElement | null };
    buttonsRef.current.set(index, created);
    return created;
  }

  // Restoring focus after a move is what keeps this control keyboard-operable.
  // Both buttons are natively `disabled` at the ends of the list, so moving an
  // item TO an end disables the very button that performed the move — the
  // browser then drops focus to `<body>` and the respondent's keyboard path
  // dead-ends mid-task, looking exactly like "ranking doesn't respond to the
  // keyboard". Focus follows the item instead: its own button when that is
  // still enabled, otherwise the counterpart, which is always enabled because
  // a list long enough to reorder cannot disable both.
  //
  // `useLayoutEffect`, not `useEffect`: this must land before the browser
  // paints, or focus visibly flickers through `<body>`.
  useLayoutEffect(() => {
    const pending = pendingFocusRef.current;
    if (pending === null) return;
    pendingFocusRef.current = null;

    const refs = buttonsRef.current.get(pending.index);
    if (refs === undefined) return;

    const acting = pending.delta < 0 ? refs.up : refs.down;
    const counterpart = pending.delta < 0 ? refs.down : refs.up;
    const target =
      acting !== null && !acting.disabled ? acting : counterpart;
    if (target !== null && !target.disabled) target.focus();
  }, [ranking]);

  // No `next !== ranking` guard here. `moveRankItem` does return the same
  // reference for an out-of-range move, but the only way to request one is the
  // arrow at an end of the list — and those are natively `disabled`, so the
  // click never reaches this handler. A second guard would be an unreachable
  // branch: dead code that a coverage gate can only certify, never exercise.
  // `moveRankItem`'s defensive same-reference return stays pinned by its own
  // unit test, where it is a meaningful property of the pure function.
  function move(index: number, delta: number): void {
    // The landing position, which is where the handles to focus will live after
    // the re-render. `moveRankItem` splices the item out and back in at
    // index + delta, and the arrows that would leave the list are `disabled`, so
    // this is always in range by the time it is used.
    pendingFocusRef.current = { index: index + delta, delta };
    onChange(moveRankItem(ranking, index, delta));
  }

  return (
    <div>
      <p className="mb-cog-2 text-body-sm text-cog-text-secondary">
        {m.ask_survey_preview_rank_hint()}
      </p>
      <ol aria-labelledby={labelledBy} className="flex flex-col gap-cog-2">
        {ranking.map((item, index) => (
          <li
            // Position-qualified: a bare `item` collides when two options share
            // a label, and React then reuses the wrong row.
            key={`${index}-${item}`}
            className="flex items-center gap-cog-3 rounded-md border border-cog-border bg-cog-surface-subtle px-cog-3 py-cog-2"
          >
            <span
              aria-hidden="true"
              className="min-w-cog-5 text-body-sm font-semibold tabular-nums text-cog-text-tertiary"
            >
              {index + 1}
            </span>
            <span
              data-i18n-allow="data"
              className="flex-1 text-body-md text-cog-text-primary"
            >
              {item}
            </span>
            {/* The position is exposed as text rather than only through the
                visual number, so a screen-reader user hears where the item
                landed after a move without inspecting the list. */}
            <span className="sr-only">
              {m.ask_survey_preview_rank_position({
                position: index + 1,
                total: ranking.length,
              })}
            </span>
            <div className="flex items-center gap-cog-1">
              <button
                type="button"
                ref={(node) => {
                  handles(index).up = node;
                }}
                onClick={() => move(index, -1)}
                disabled={index === 0}
                aria-label={m.ask_survey_preview_rank_move_up({ item })}
                className="inline-flex h-cog-7-5 w-cog-7-5 items-center justify-center rounded-md text-cog-text-secondary transition-colors duration-standard hover:bg-cog-surface-muted hover:text-cog-text-primary focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus disabled:text-cog-text-tertiary"
              >
                <ArrowUp aria-hidden="true" className="h-cog-4 w-cog-4" />
              </button>
              <button
                type="button"
                ref={(node) => {
                  handles(index).down = node;
                }}
                onClick={() => move(index, 1)}
                disabled={index === ranking.length - 1}
                aria-label={m.ask_survey_preview_rank_move_down({ item })}
                className="inline-flex h-cog-7-5 w-cog-7-5 items-center justify-center rounded-md text-cog-text-secondary transition-colors duration-standard hover:bg-cog-surface-muted hover:text-cog-text-primary focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus disabled:text-cog-text-tertiary"
              >
                <ArrowDown aria-hidden="true" className="h-cog-4 w-cog-4" />
              </button>
            </div>
          </li>
        ))}
      </ol>
    </div>
  );
}



